-- Backfill Airport.city/Airport.state from the OurAirports source CSV
-- (user-provided, "ITEM 1" in BACKLOG.md) for the airports already in the
-- table. Does NOT touch which airports exist — only sets city/state on
-- matching rows by icao, so the carefully filtered dataset from the two
-- prior airport migrations (worldwide large/medium, US small airports with
-- a runway >= 3000ft) is preserved exactly as-is. Matched by "icao_code"
-- (falling back to "ident") from the source CSV, the same fallback OurAirports
-- itself derives and the same one the original re-import used to pick each
-- row's icao — a row whose icao doesn't match any existing Airport is simply
-- a no-op, not an error, so this is safe to run even though the source CSV
-- includes far more airports than JetDeck actually kept.

ALTER TABLE "Airport" ADD COLUMN "city" TEXT;
ALTER TABLE "Airport" ADD COLUMN "state" TEXT;

UPDATE "Airport" a
SET city = v.city, state = v.state
